import { call, put, takeEvery } from 'redux-saga/effects';
import type { SagaIterator } from 'redux-saga';
import type { PayloadAction } from '@reduxjs/toolkit';

function* searchProducts(action: PayloadAction<string>): SagaIterator {
  try {
    const items: Product[] = yield call(api.search, action.payload);
    yield put(searchSucceeded(items));
  } catch (e) {
    yield put(searchFailed(String(e)));
  }
}

export function* watchSearch(): SagaIterator {
  yield takeEvery(searchChanged.type, searchProducts);
}

function* syncInbox(token: string): SagaIterator {
  while (true) {
    const messages: Message[] = yield call(api.fetchInbox, token);
    yield put(inboxReceived(messages));
    yield delay(15_000);
  }
}

export function* authFlow(): SagaIterator {
  while (true) {
    const { payload }: PayloadAction<Credentials> = yield take(loginRequested.type);
    const token: string = yield call(api.login, payload);
    yield put(loginSucceeded(token));
    yield call(syncInbox, token);
    yield take(logoutRequested.type);
    yield put(sessionCleared());
  }
}

function* uploadEvents(action: PayloadAction<AnalyticsEvent[]>): SagaIterator {
  const batch = action.payload;
  yield call(api.uploadEvents, batch);
  yield put(eventsUploaded(batch.length));
}

function* loadCart(): SagaIterator {
  try {
    const cart: Cart = yield call(api.fetchCart);
    yield put(cartLoaded(cart));
  } catch (e) {
    yield put(cartFailed(String(e)));
  }
}

export function* rootSaga(): SagaIterator {
  yield all([
    takeEvery(eventsFlushed.type, uploadEvents),
    takeEvery(cartRequested.type, loadCart),
    fork(watchAuth),
  ]);
}
